// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    // fuzz the timestamp we will warp to (uint256 ts) and a caller address (address caller)
    function testFuzz_property(uint256 ts, address caller) public {
        // keep timestamp in sensible range: nonzero and within uint32-ish recent range to avoid absurd warps
        // but keep it wide so fuzzer can find equality/ordering cases.
        vm.assume(ts <= type(uint32).max);
        vm.assume(caller != address(0));

        // fund caller so it can send 10 ether
        vm.deal(caller, 20 ether);

        // record old pastBlockTime
        uint256 old = c.pastBlockTime();

        // warp to ts
        vm.warp(ts);

        // impersonate caller and call fallback with exactly 10 ether
        vm.prank(caller);
        bool ok;
        // call the fallback via low-level call so we can send value; fallback is payable
        // try/catch around external call to observe success
        (bool success, ) = address(c).call{value: 10 ether}("");
        ok = success;

        // For the correct contract, any successful call with exactly 10 ether requires block.timestamp > old
        // and thus pastBlockTime after call must be strictly greater than old. We assert that when the call succeeded.
        if (ok) {
            uint256 after_ = c.pastBlockTime();
            assertTrue(after_ > old);
        } else {
            // If call reverted, nothing required by this property (the require may have prevented it)
            assertTrue(true);
        }
    }
}
